// Instagram long-lived tokens last 60 days. This refresh extends it another 60.
// An expired token is the single most common silent failure in this stack, so the
// email below is deliberately loud and tells you exactly what to do.
const t = $input.first().json;
const days = Math.round((Number(t.expires_in) || 0) / 86400);
const expiresOn = new Date(Date.now() + (Number(t.expires_in) || 0) * 1000)
  .toISOString().slice(0, 10);

return [{
  json: {
    days,
    expiresOn,
    token: t.access_token || '',
    subject: `[Foundry] Instagram token refreshed - paste into n8n (expires ${expiresOn})`,
    body: [
      'The Instagram long-lived token was refreshed automatically.',
      '',
      `New token expires: ${expiresOn} (${days} days).`,
      '',
      'ACTION REQUIRED - the refresh does NOT update the stored credential:',
      '  1. Open n8n at http://127.0.0.1:5678',
      '  2. Credentials -> "Meta Graph - prompt2eat"',
      '  3. Replace the access token with the one below, save.',
      '  4. Update REPLACE_WITH_CURRENT_LONG_LIVED_TOKEN in WF4 as well.',
      '',
      'New token:',
      t.access_token || '(none returned - check the error)',
      '',
      'If you do nothing, Instagram posting stops silently when the old token expires.'
    ].join('\n')
  }
}];

// The refresh call itself failed - that is worse than a successful refresh,
// because posting will stop within days and nothing else will tell you.
return [{
  json: {
    subject: '[Foundry] URGENT - Instagram token refresh FAILED',
    body: [
      'The monthly Instagram token refresh did not succeed.',
      '',
      'Instagram posting (WF1) will stop silently when the current token expires,',
      'which is at most 60 days after it was last issued.',
      '',
      'Fix: generate a new long-lived token in the Meta developer console,',
      'paste it into the n8n credential "Meta Graph - prompt2eat", and update',
      'REPLACE_WITH_CURRENT_LONG_LIVED_TOKEN in WF4.',
      '',
      'Error detail:',
      JSON.stringify($input.first().json, null, 2)
    ].join('\n')
  }
}];
